# Conway's Game of Life on a small torus: a glider crossing the board.
W = 20
H = 10


def step(cells: set[tuple[int, int]]) -> set[tuple[int, int]]:
    counts: dict[tuple[int, int], int] = {}
    for x, y in cells:
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx != 0 or dy != 0:
                    k = ((x + dx) % W, (y + dy) % H)
                    counts[k] = counts.get(k, 0) + 1
    return {k for k, n in counts.items() if n == 3 or (n == 2 and k in cells)}


def show(cells: set[tuple[int, int]]) -> str:
    return "\n".join("".join("█" if (x, y) in cells else "·" for x in range(W)) for y in range(H))


cells = {(1, 0), (2, 1), (0, 2), (1, 2), (2, 2)}
for gen in range(0, 9, 4):
    print(f"generation {gen}")
    print(show(cells))
    for _ in range(4):
        cells = step(cells)

# The sieve of Eratosthenes up to 200,000.
def primes(n: int) -> list[int]:
    sieve = [True] * (n + 1)
    sieve[0] = False
    sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i, p in enumerate(sieve) if p]


ps = primes(200000)
print(len(ps), ps[:10], ps[-3:])

# The N-queens puzzle by backtracking: count all solutions, draw the first.
def solve(n: int) -> list[list[int]]:
    found: list[list[int]] = []
    cols: list[int] = []

    def place(row: int) -> None:
        if row == n:
            found.append(cols.copy())
            return
        for c in range(n):
            if all(c != q and abs(c - q) != row - r for r, q in enumerate(cols)):
                cols.append(c)
                place(row + 1)
                cols.pop()

    place(0)
    return found


for n in range(4, 9):
    print(f"{n} queens: {len(solve(n))} solutions")
first = solve(8)[0]
for c in first:
    print(" ".join("Q" if i == c else "." for i in range(8)))

# Sorting algorithms, checked against sorted().
class Rng:
    """A linear congruential generator (the constants of C's rand)."""

    def __init__(self, seed: int) -> None:
        self.state = seed

    def next(self) -> int:
        self.state = (self.state * 1103515245 + 12345) % 2147483648
        return self.state >> 8

    def below(self, n: int) -> int:
        return self.next() % n


def quicksort(xs: list[int]) -> list[int]:
    if len(xs) <= 1:
        return xs
    p = xs[len(xs) // 2]
    return quicksort([x for x in xs if x < p]) + [x for x in xs if x == p] + quicksort([x for x in xs if x > p])


def merge_sort(xs: list[int]) -> list[int]:
    if len(xs) <= 1:
        return xs
    m = len(xs) // 2
    a = merge_sort(xs[:m])
    b = merge_sort(xs[m:])
    out: list[int] = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]


def insertion_sort(xs: list[int]) -> list[int]:
    ys = xs.copy()
    for i in range(1, len(ys)):
        k = ys[i]
        j = i - 1
        while j >= 0 and ys[j] > k:
            ys[j + 1] = ys[j]
            j -= 1
        ys[j + 1] = k
    return ys


rng = Rng(1)
data = [rng.below(1000) for _ in range(2000)]
expected = sorted(data)
print("     quicksort:", quicksort(data) == expected)
print("    merge sort:", merge_sort(data) == expected)
print("insertion sort:", insertion_sort(data) == expected)
print("first ten:", sorted(data)[:10])

# Word counting with a dict, sorted by count.
text = """the quick brown fox jumps over the lazy dog
the dog barks and the fox runs"""
counts: dict[str, int] = {}
for w in text.split():
    counts[w] = counts.get(w, 0) + 1
top = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
for word, n in top:
    print(f"{word:>6} {'#' * n} {n}")
print(len(counts), "distinct words;", sum(counts.values()), "in all")
